using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;using EmulatorHub;
class RowPaintTests{static long Hash(Bitmap b){long h=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)h=unchecked(h*31+b.GetPixel(x,y).ToArgb());return h;}[STAThread]static void Main(){Application.EnableVisualStyles();var data=Store.Load();NextData.Ensure(data);data.Emulators=new List<EmulatorProfile>{new EmulatorProfile{Id="probe",Name="Paint fixture",Executable=Application.ExecutablePath}};data.Games.Clear();Store.Save(data);using(var form=new MainForm(true)){var list=(ListView)typeof(MainForm).GetField("emulatorList",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(form);var item=list.Items[0];item.Selected=true;using(var bitmap=new Bitmap(250,48))using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(list.BackColor);var bounds=new Rectangle(0,0,250,48);var args=new DrawListViewSubItemEventArgs(graphics,bounds,item,item.SubItems[2],0,2,list.Columns[2],ListViewItemStates.Selected);var paint=typeof(ListView).GetMethod("OnDrawSubItem",BindingFlags.NonPublic|BindingFlags.Instance);paint.Invoke(list,new object[]{args});long first=Hash(bitmap);Color before=bitmap.GetPixel(240,20);paint.Invoke(list,new object[]{args});if(first!=Hash(bitmap))throw new Exception("Identical row redraw changes its pixels");Console.WriteLine("PASS: 1 repeated row paint check.");Console.WriteLine("Background: "+before+" -> "+bitmap.GetPixel(240,20));}}}}
